-- V3 增量迁移：保留全部 V2 表和历史数据。
create table if not exists public.goal_nodes(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,parent_id uuid references public.goal_nodes(id) on delete set null,level text not null check(level in('annual','monthly','weekly')),title text not null,description text,category text,progress_type text not null default 'task' check(progress_type in('numeric','task','milestone','habit')),source_type text,target_value numeric not null default 0,unit text not null default '项',sort_order integer not null default 0,status text not null default 'active',starts_on date,ends_on date,completed_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.goal_milestones(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,goal_id uuid not null references public.goal_nodes(id) on delete cascade,title text not null,sort_order integer not null default 0,completed_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.action_tasks(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,title text not null,description text,category text,goal_id uuid references public.goal_nodes(id) on delete set null,planned_date date not null,priority smallint not null default 1 check(priority between 0 and 2),estimated_minutes integer not null default 0 check(estimated_minutes>=0),recurrence_rule jsonb not null default '{"type":"none"}'::jsonb,status text not null default 'active',sort_order integer not null default 0,source_key text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(user_id,source_key));
create table if not exists public.task_occurrences(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,task_id uuid not null references public.action_tasks(id) on delete cascade,occurrence_date date not null,status text not null default 'pending',actual_minutes integer not null default 0 check(actual_minutes>=0),completed_at timestamptz,sort_order integer not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(user_id,task_id,occurrence_date));
create table if not exists public.daily_journals(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,journal_date date not null,mood text,what_happened text,achievement text,gratitude text,tomorrow_plan text,tomorrow_top_three jsonb not null default '[]'::jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(user_id,journal_date));
create table if not exists public.journal_drafts(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,journal_date date not null,draft jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(user_id,journal_date));
create table if not exists public.journal_images(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,journal_id uuid not null references public.daily_journals(id) on delete cascade,storage_path text not null,mime_type text not null check(mime_type in('image/jpeg','image/png','image/webp')),byte_size integer not null check(byte_size between 1 and 5242880),sort_order integer not null default 0,created_at timestamptz not null default now(),unique(user_id,storage_path));
create index if not exists idx_goal_nodes_user_parent on public.goal_nodes(user_id,parent_id,sort_order);
create index if not exists idx_action_tasks_user_date on public.action_tasks(user_id,planned_date);
create index if not exists idx_occurrences_user_date on public.task_occurrences(user_id,occurrence_date,status);
create index if not exists idx_journals_user_date on public.daily_journals(user_id,journal_date desc);
do $$ declare t text; begin foreach t in array array['goal_nodes','goal_milestones','action_tasks','task_occurrences','daily_journals','journal_drafts','journal_images'] loop execute format('alter table public.%I enable row level security',t);execute format('drop policy if exists "owner_all" on public.%I',t);execute format('create policy "owner_all" on public.%I for all using (auth.uid()=user_id) with check (auth.uid()=user_id)',t);end loop;end $$;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('journal-images','journal-images',false,5242880,array['image/jpeg','image/png','image/webp']) on conflict(id) do update set public=false,file_size_limit=excluded.file_size_limit,allowed_mime_types=excluded.allowed_mime_types;
drop policy if exists "journal_images_select_own" on storage.objects;drop policy if exists "journal_images_insert_own" on storage.objects;drop policy if exists "journal_images_update_own" on storage.objects;drop policy if exists "journal_images_delete_own" on storage.objects;
create policy "journal_images_select_own" on storage.objects for select using(bucket_id='journal-images' and(storage.foldername(name))[1]=auth.uid()::text);
create policy "journal_images_insert_own" on storage.objects for insert with check(bucket_id='journal-images' and(storage.foldername(name))[1]=auth.uid()::text);
create policy "journal_images_update_own" on storage.objects for update using(bucket_id='journal-images' and(storage.foldername(name))[1]=auth.uid()::text);
create policy "journal_images_delete_own" on storage.objects for delete using(bucket_id='journal-images' and(storage.foldername(name))[1]=auth.uid()::text);

